import React, {
  ComponentProps,
  ElementRef,
  useRef,
  MutableRefObject,
  useState,
  useCallback,
  useEffect,
} from 'react';
import { ChevronRight, ChevronLeft } from '@hexa-ui/icons';
import * as TabsPrimitive from '@radix-ui/react-tabs';
import {
  StyledTabs,
  StyledTabsContent,
  StyledTabsList,
  StyledTabsTrigger,
  TabsListContainer,
  Box,
  ArrowButton,
} from './Tabs.styles';
import { Divider } from '../divider';

// Types
export type TabsListPrimitiveProps = ComponentProps<typeof TabsPrimitive.List>;

export type TabsListProps = Omit<TabsListPrimitiveProps, 'nonce'>;

export type TabsProps = React.ComponentProps<typeof TabsPrimitive.Root> & {
  defaultValue: string;
};

// Components
export const Tabs = ({ children, defaultValue, ...props }: TabsProps): JSX.Element => (
  <StyledTabs defaultValue={defaultValue} {...props}>
    {children}
  </StyledTabs>
);

export const TabsTrigger = StyledTabsTrigger;

export const TabsContent = StyledTabsContent;

export const TabsList = React.forwardRef<ElementRef<typeof StyledTabsList>, TabsListProps>(
  ({ children, ...props }, forwardedRef) => {
    const elementRef = useRef<HTMLDivElement | null>(null);
    const lastChildRef = useRef<HTMLDivElement | null>(null);
    const firstChildRef = useRef<HTMLDivElement | null>(null);
    const rootRef = (forwardedRef as MutableRefObject<HTMLDivElement>) || elementRef;
    const [showLeftArrow, setShowLeftArrow] = useState(false);
    const [showRightArrow, setShowRightArrow] = useState(false);
    /* istanbul ignore next */
    const scrollLeft = useCallback(() => {
      const element = elementRef.current;
      if (element) {
        const x = element.scrollLeft;
        element?.scrollTo(x + 30, 0);
      }
    }, []);
    /* istanbul ignore next */
    const scrollRight = useCallback(() => {
      const element = elementRef.current;
      if (element) {
        const x = element.scrollLeft;
        element?.scrollTo(x - 30, 0);
      }
    }, []);
    /* istanbul ignore next */
    useEffect(() => {
      const options = {
        root: rootRef.current,
        rootMargin: '0px',
        threshold: 0.99,
      };
      const currentLastChildRef = lastChildRef.current;
      const currentFirstChildRef = firstChildRef.current;

      const lastChildObserver = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) {
            setShowRightArrow(true);
            return;
          }
          setShowRightArrow(false);
        });
      }, options);

      if (currentLastChildRef) {
        lastChildObserver.observe(currentLastChildRef);
      }

      const firstChildObserver = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) {
            setShowLeftArrow(true);
            return;
          }
          setShowLeftArrow(false);
        });
      }, options);
      if (currentFirstChildRef) {
        firstChildObserver.observe(currentFirstChildRef);
      }

      return () => {
        if (currentLastChildRef) {
          lastChildObserver.unobserve(currentLastChildRef);
        }
        if (currentFirstChildRef) {
          firstChildObserver.unobserve(currentFirstChildRef);
        }
      };
    }, [elementRef, rootRef]);
    return (
      <>
        <Box>
          {
            /* istanbul ignore next */
            showLeftArrow ? (
              <ArrowButton>
                <ChevronLeft onClick={() => scrollRight()} size="medium" role="button" />
              </ArrowButton>
            ) : null
          }
          <TabsListContainer>
            <StyledTabsList {...props} ref={rootRef}>
              {React.Children.map(
                children as React.ReactElement[],
                (child: React.ReactElement, index: number) =>
                  React.cloneElement(child, {
                    ...child.props,
                    ...(index === 0 && { ref: firstChildRef }),
                    ...(index === React.Children.count(children) - 1 && {
                      ref: lastChildRef,
                    }),
                  })
              )}
            </StyledTabsList>
          </TabsListContainer>
          {
            /* istanbul ignore next */
            showRightArrow ? (
              <ArrowButton>
                <ChevronRight onClick={() => scrollLeft()} size="medium" role="button" />
              </ArrowButton>
            ) : null
          }
        </Box>
        <Divider />
      </>
    );
  }
);
